package com.opspilot.incident.infrastructure.persistence;
import com.opspilot.incident.domain.*; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="incidents") class IncidentEntity { @Id UUID id; @Column(name="service_id") UUID serviceId; String fingerprint; @Enumerated(EnumType.STRING) IncidentStatus status; @Enumerated(EnumType.STRING) Severity severity; String title; @Column(name="resolution_summary") String resolutionSummary; @Column(name="created_at") Instant createdAt; @Column(name="updated_at") Instant updatedAt; @Version long version; protected IncidentEntity(){} IncidentEntity(UUID id,UUID serviceId,String fingerprint,Severity severity,String title,Instant now){this.id=id;this.serviceId=serviceId;this.fingerprint=fingerprint;this.status=IncidentStatus.OPEN;this.severity=severity;this.title=title;this.createdAt=now;this.updatedAt=now;} }
